INSERT INTO feature VALUES('dependent-case','types','Dependent case analysis','nominal-data','implemented','notable',NULL,'A case over a variable answers at a motive that abstracts the scrutinee, with no motive clause written, and generalises that motive over each later binder whose type reads the scrutinee and that an arm or the motive reads; over a family with parameters, whose motive the lowering keeps as written, the checker reads the scrutinee as the motive''s binder and as each arm''s constructor. A case on a sum, a `Bool` among them, and a split of the unit read their goal as that motive, and each arm reads the scrutinee at its injection or at `*{}`, in both checkers.','core-checker kernel-core','corpus/model/identity/open-fold.gandr corpus/model/universe/code-beside-value.gandr corpus/model/data/motive-later-binder.gandr corpus/model/data/motive-parameterised.gandr corpus/model/data/motive-bool-unit.gandr','corpus/model/identity/open-fold.gandr','#370');
